/**
 * Per-member project mutes, consulted by the fan-out and the digest build.
 */
import { and, eq } from "drizzle-orm";
import { getDb, notificationProjectMutes } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId } from "./_mappers";
import { orgPredicate } from "./base-repository";
import type { OrgId, ProjectId, UserId } from "@/types/common";

/** Idempotent: muting a project the member already muted is a no-op. */
export async function insertMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .insert(notificationProjectMutes)
    .values({
      orgId,
      userId,
      projectId,
      createdAt: toIsoTimestamp(new Date()),
    })
    .onConflictDoNothing({
      target: [
        notificationProjectMutes.orgId,
        notificationProjectMutes.userId,
        notificationProjectMutes.projectId,
      ],
    })
    .run();
}

export async function deleteMute(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<void> {
  getDb()
    .delete(notificationProjectMutes)
    .where(
      and(
        orgPredicate(notificationProjectMutes.orgId, orgId),
        eq(notificationProjectMutes.userId, userId),
        eq(notificationProjectMutes.projectId, projectId),
      ),
    )
    .run();
}

export async function listMutedProjectIds(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ProjectId[]> {
  const rows = getDb()
    .select({ projectId: notificationProjectMutes.projectId })
    .from(notificationProjectMutes)
    .where(
      and(
        orgPredicate(notificationProjectMutes.orgId, orgId),
        eq(notificationProjectMutes.userId, userId),
      ),
    )
    .all();
  return rows.map((row) => brandId<ProjectId>(row.projectId));
}

export async function isProjectMuted(
  orgId: OrgId,
  userId: UserId,
  projectId: ProjectId,
): Promise<boolean> {
  const row = getDb()
    .select({ projectId: notificationProjectMutes.projectId })
    .from(notificationProjectMutes)
    .where(
      and(
        orgPredicate(notificationProjectMutes.orgId, orgId),
        eq(notificationProjectMutes.userId, userId),
        eq(notificationProjectMutes.projectId, projectId),
      ),
    )
    .get();
  return row !== undefined;
}

