/**
 * Silences one project for the actor alone. Idempotent, and guarded the same
 * way as reading the project: org scope, then existence, then `project:read`.
 */
export async function muteProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  await assertProjectReadable(actor, orgId, projectId);
  await muteRepo.insertMute(orgId, actor.userId, projectId);
}

/** Lifts the actor's own mute on a project. Idempotent, same guards as `muteProject`. */
export async function unmuteProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  await assertProjectReadable(actor, orgId, projectId);
  await muteRepo.deleteMute(orgId, actor.userId, projectId);
}

/** The projects the actor has muted in this org; never another member's mutes. */
export async function listMutedProjectIds(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly ProjectId[]> {
  assertOrgScope(actor, orgId);
  return muteRepo.listMutedProjectIds(orgId, actor.userId);
}

async function assertProjectReadable(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:read", projectResource(project));
}

