import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { TenantScopeError } from "@/lib/tenant";
import * as digestService from "@/server/services/digest-service";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as notificationService from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ProjectId, UserId } from "@/types/common";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("mutecheck", "growth");
  other = await createTenant("mutecheck-other", "growth");
});

afterAll(() => {
  cleanup();
});

describe("mute check", () => {
  it("mutes idempotently, lists, and unmutes", async () => {
    const pid = tenant.project.id;
    await notificationService.muteProject(tenant.actors.member, tenant.org.id, pid);
    await notificationService.muteProject(tenant.actors.member, tenant.org.id, pid);
    expect(await notificationService.listMutedProjectIds(tenant.actors.member, tenant.org.id)).toEqual([pid]);
    expect(await notificationService.listMutedProjectIds(tenant.actors.admin, tenant.org.id)).toEqual([]);
    await notificationService.unmuteProject(tenant.actors.member, tenant.org.id, pid);
    await notificationService.unmuteProject(tenant.actors.member, tenant.org.id, pid);
    expect(await notificationService.listMutedProjectIds(tenant.actors.member, tenant.org.id)).toEqual([]);
  });

  it("applies TenantScopeError and NotFoundError guards", async () => {
    await expect(
      notificationService.muteProject(tenant.actors.member, other.org.id, tenant.project.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      notificationService.muteProject(tenant.actors.member, tenant.org.id, "PRJ-missing" as ProjectId),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("notify: muted project keeps personal kinds in-app only, drops the rest", async () => {
    const pid = tenant.project.id;
    await notificationService.muteProject(tenant.actors.viewer, tenant.org.id, pid);

    const personal = await notificationService.notify(
      tenant.org.id,
      "issue_assigned",
      [tenant.userIds.viewer],
      { title: "a", body: "a", href: "/x", actorId: null, projectId: pid },
    );
    expect(personal).toHaveLength(1);
    expect(personal[0]?.channels).toEqual(["in_app"]);
    expect(personal[0]?.projectId).toBe(pid);

    const other_kind = await notificationService.notify(
      tenant.org.id,
      "comment_created",
      [tenant.userIds.viewer],
      { title: "b", body: "b", href: "/x", actorId: null, projectId: pid },
    );
    expect(other_kind).toHaveLength(0);

    const nonProject = await notificationService.notify(
      tenant.org.id,
      "comment_created",
      [tenant.userIds.viewer],
      { title: "c", body: "c", href: "/x", actorId: null },
    );
    expect(nonProject).toHaveLength(1);
    await notificationService.unmuteProject(tenant.actors.viewer, tenant.org.id, pid);
  });

  it("digest leaves out muted-project entries until unmute, cap applies after", async () => {
    const pid = tenant.project.id;
    const recipient = tenant.userIds.member as UserId;
    const now = new Date();
    const windowStart = new Date(now.getTime() - 86_400_000).toISOString() as never;
    const windowEnd = new Date(now.getTime() + 60_000).toISOString() as never;

    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
      recipientId: recipient,
      kind: "comment_created",
      title: "muted-one",
      body: "x",
      href: "/x",
      actorId: null,
      projectId: pid,
      channels: ["email"],
    });
    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
      recipientId: recipient,
      kind: "comment_created",
      title: "free-one",
      body: "x",
      href: "/x",
      actorId: null,
      channels: ["email"],
    });

    await notificationService.muteProject(tenant.actors.member, tenant.org.id, pid);
    const muted = await digestService.buildDigest(tenant.org.id, recipient, windowStart, windowEnd);
    expect(muted?.entries.map((e) => e.title)).toEqual(["free-one"]);

    await notificationService.unmuteProject(tenant.actors.member, tenant.org.id, pid);
    const unmuted = await digestService.buildDigest(tenant.org.id, recipient, windowStart, windowEnd);
    expect(unmuted?.entries.map((e) => e.title).sort()).toEqual(["free-one", "muted-one"]);
  });

  it("digest is null when everything left is muted", async () => {
    const pid = tenant.project.id;
    const recipient = tenant.userIds.viewer as UserId;
    const now = new Date();
    const windowStart = new Date(now.getTime() - 86_400_000).toISOString() as never;
    const windowEnd = new Date(now.getTime() + 60_000).toISOString() as never;
    await notificationRepo.insertNotification(tenant.org.id, {
      orgId: tenant.org.id,
      recipientId: recipient,
      kind: "comment_created",
      title: "only-muted",
      body: "x",
      href: "/x",
      actorId: null,
      projectId: pid,
      channels: ["email"],
    });
    await notificationService.muteProject(tenant.actors.viewer, tenant.org.id, pid);
    expect(await digestService.buildDigest(tenant.org.id, recipient, windowStart, windowEnd)).toBeNull();
  });
});

